-- ── teething_care_tips → ru (8 sətir) ──
UPDATE public.teething_care_tips SET title_ru = COALESCE(title_ru, 'Безопасные прорезыватели'), content_ru = COALESCE(content_ru, 'Выбирайте нетоксичные прорезыватели без бисфенола А (BPA). Избегайте игрушек с мелкими деталями, которыми малыш может подавиться.') WHERE id = '30255b45-90fc-46ab-8b8c-9ce75952377f';
UPDATE public.teething_care_tips SET title_ru = COALESCE(title_ru, 'Уход за первым зубом'), content_ru = COALESCE(content_ru, 'Как только появится первый зуб, начинайте чистить его мягкой детской зубной щёткой, используя только воду.') WHERE id = '3fbd0995-1618-49b3-aa8c-f8ff75c52bc6';
UPDATE public.teething_care_tips SET title_ru = COALESCE(title_ru, 'Избегайте сахара'), content_ru = COALESCE(content_ru, 'Чтобы предотвратить ранний кариес, избегайте сладких продуктов и напитков, особенно перед сном.') WHERE id = '5c0c2cd7-bbc3-4acf-aa29-a75ff9325110';
UPDATE public.teething_care_tips SET title_ru = COALESCE(title_ru, 'Регулярные визиты к стоматологу'), content_ru = COALESCE(content_ru, 'Запланируйте первый визит малыша к стоматологу после появления первого зуба, но не позднее его первого дня рождения.') WHERE id = '5d8e7654-1e68-474f-b792-610a380b7688';
UPDATE public.teething_care_tips SET title_ru = COALESCE(title_ru, 'Охлаждённые прорезыватели'), content_ru = COALESCE(content_ru, 'Храните прорезыватели в холодильнике. Никогда не замораживайте их: они могут оказаться слишком холодными для дёсен малыша.') WHERE id = '6e21f5d7-f642-4d33-9bfc-bd32e68b561c';
UPDATE public.teething_care_tips SET title_ru = COALESCE(title_ru, 'Профилактика раздражения от слюны'), content_ru = COALESCE(content_ru, 'Следите, чтобы подбородок и шея малыша оставались сухими. Для предотвращения раздражения от слюны наносите мягкий защитный крем.') WHERE id = '9dc209b1-6f09-4b82-b44f-3bc06493d519';
